/**
 * Benchmark data from `simulation-results.json`.
 *
 * ## Why this answers 200 on a fresh clone
 *
 * The file is generated by `npm run simulate` and is gitignored, so **its absence is the default
 * state of a correct checkout**, not a fault. Answering 404 or 500 there makes a fresh clone look
 * broken; answering 200 with `available:false` states the truth and lets the dashboard render its
 * "run the simulation" empty state without special-casing an error.
 *
 * The five names below - `agents`, `memoryCommits`, `reputationEvents`, `crossModelSimilarity` and
 * `benchmarks{...}` - are load-bearing for the dashboard's charts, so they are **always present**,
 * empty when there is no file. No view has to branch on a missing key.
 *
 * ## Why the read is async, cached and capped
 *
 * v1 ran `fs.existsSync` + `fs.readFileSync` + `JSON.parse` on the event loop for every request.
 * Here the read is async, keyed on `mtime` and `size` so repeated polls re-parse nothing, capped at
 * {@link MAX_FILE_BYTES}, and a parse failure becomes an explicit `simulation_corrupt` rather than
 * a stack trace - the simulator writes the file non-atomically today, so a half-written file is
 * genuinely reachable.
 *
 * @module src/routes/simulation
 */
import { readFile, stat } from 'node:fs/promises';

import { Router } from 'express';

import { errors } from '../errors.js';
import { asyncHandler } from '../middleware/asyncHandler.js';

/** Hard cap on the file this route will read into memory. */
export const MAX_FILE_BYTES = 8 * 1024 * 1024;

/** The empty benchmark block, so every consumer sees the same five arrays. */
const EMPTY_BENCHMARKS = Object.freeze({
  embeddingLatencies: [],
  encryptionLatencies: [],
  ipfsLatencies: [],
  blockchainLatencies: [],
  totalLatencies: [],
});

/**
 * The body returned when there is no file, or the file cannot be used.
 *
 * @param {string} reason Why nothing is available.
 * @param {string} path The configured path, so an operator knows where it was looked for.
 * @returns {Record<string, any>} The empty-but-valid document.
 */
export function emptySimulation(reason, path) {
  return {
    available: false,
    reason,
    hint: 'Run `npm run simulate` to generate benchmark data on this node.',
    path,
    generatedAt: null,
    agents: [],
    memoryCommits: [],
    reputationEvents: [],
    crossModelSimilarity: [],
    benchmarks: { ...EMPTY_BENCHMARKS },
  };
}

/**
 * Normalise a parsed file into the published shape.
 *
 * A v1 file (no `specHash`) passes through with its five arrays guaranteed; a v2 file keeps its
 * richer fields (`nullControl`, `chiSquare`, `noiseBaseline`, per-primitive timings, `specHash`,
 * `paramsId`) as additive keys the current dashboard ignores and an updated one can render.
 *
 * @param {any} data Parsed file contents.
 * @param {string} path Source path.
 * @param {string} generatedAt File mtime, as an ISO string.
 * @returns {Record<string, any>} The response body.
 */
export function normaliseSimulation(data, path, generatedAt) {
  const source = data && typeof data === 'object' ? data : {};
  /**
   * @param {unknown} value Candidate.
   * @returns {unknown[]} The value when it is an array, else an empty array.
   */
  const arr = (value) => (Array.isArray(value) ? value : []);
  const benchmarks =
    source.benchmarks && typeof source.benchmarks === 'object' ? source.benchmarks : {};

  return {
    ...source,
    available: true,
    reason: null,
    hint: null,
    path,
    generatedAt: typeof source.generatedAt === 'string' ? source.generatedAt : generatedAt,
    schema: typeof source.specHash === 'string' ? 'v2' : 'v1',
    agents: arr(source.agents),
    memoryCommits: arr(source.memoryCommits),
    reputationEvents: arr(source.reputationEvents),
    crossModelSimilarity: arr(source.crossModelSimilarity),
    benchmarks: {
      ...benchmarks,
      embeddingLatencies: arr(benchmarks.embeddingLatencies),
      encryptionLatencies: arr(benchmarks.encryptionLatencies),
      ipfsLatencies: arr(benchmarks.ipfsLatencies),
      blockchainLatencies: arr(benchmarks.blockchainLatencies),
      totalLatencies: arr(benchmarks.totalLatencies),
    },
  };
}

/**
 * Build the simulation route.
 *
 * @param {object} deps Dependencies.
 * @param {Record<string, any>} deps.config Application config.
 * @returns {import('express').Router} The router.
 */
export function createSimulationRoutes({ config }) {
  const router = Router();
  const path = config.paths.simulationResults;

  /** @type {{key: string, value: Record<string, any>}|null} */
  let cache = null;

  router.get(
    '/',
    asyncHandler(async (_req, res) => {
      /** @type {import('node:fs').Stats} */
      let info;
      try {
        info = await stat(path);
      } catch {
        res
          .set('Cache-Control', 'no-cache')
          .status(200)
          .json(emptySimulation('No simulation results have been generated on this node.', path));
        return;
      }

      if (!info.isFile()) {
        res
          .set('Cache-Control', 'no-cache')
          .status(200)
          .json(emptySimulation('The configured simulation path is not a file.', path));
        return;
      }
      if (info.size > MAX_FILE_BYTES) {
        throw errors.upstream(
          `The simulation results file is ${info.size} bytes, above the ${MAX_FILE_BYTES}-byte cap ` +
            'this route will read.',
          { path, size: info.size, cap: MAX_FILE_BYTES },
        );
      }

      const key = `${info.mtimeMs}:${info.size}`;
      if (cache?.key !== key) {
        const text = await readFile(path, 'utf8');
        /** @type {any} */
        let parsed;
        try {
          parsed = JSON.parse(text);
        } catch (err) {
          // The simulator writes this file without a temp-and-rename, so a half-written file is
          // reachable in practice. Say that, rather than returning a shape the UI cannot render.
          throw errors.upstream(
            'The simulation results file is not valid JSON. It may have been read while the ' +
              'simulator was writing it; re-run `npm run simulate`.',
            { path, reason: String(/** @type {any} */ (err)?.message ?? err) },
          );
        }
        // eslint-disable-next-line require-atomic-updates -- benign single-threaded cache race; last write wins
        cache = {
          key,
          value: normaliseSimulation(parsed, path, new Date(info.mtimeMs).toISOString()),
        };
      }

      res.set('Cache-Control', 'private, max-age=10').status(200).json(cache.value);
    }),
  );

  return router;
}

export default createSimulationRoutes;
